SELECT batch_id, batch_no, product_id, sku_id, supplier_id, manufacturer_id, produce_batch_no, origin_place, produce_date, shelf_life_unit, shelf_life_value, expire_date, status, create_time, update_time FROM t_trace_batch
AND deleted_flag = #{queryForm.deletedFlag}
AND product_id = #{queryForm.productId}
AND supplier_id = #{queryForm.supplierId}
AND status = #{queryForm.status}
AND (INSTR(batch_no, #{queryForm.searchWord}) OR INSTR(produce_batch_no, #{queryForm.searchWord}))
ORDER BY batch_id DESC

